<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref } from 'vue'
import { CircleCheck, CircleClose, Delete, Download, Edit, Plus, Promotion, Refresh, Search, Upload, View } from '@element-plus/icons-vue'
import { ElButton, ElButtonGroup, ElDatePicker, ElForm, ElFormItem, ElInput, ElMessage, ElMessageBox, ElOption, ElPagination, ElSelect, ElTable, ElTableColumn, ElTag } from 'element-plus'
import PlanDetailDialog from '../components/task-plan/PlanDetailDialog.vue'
import ManualPlanDialog from '../components/task-plan/ManualPlanDialog.vue'
import SemiAutomaticPlanningDialog from '../components/schedule/SemiAutomaticPlanningDialog.vue'
import RequirementDialog from '../components/ops/RequirementDialog.vue'
import PageHeader from '../components/shell/PageHeader.vue'
import PrototypeStatePanel from '../components/shell/PrototypeStatePanel.vue'
import { requirementRows } from '../mocks/requirements'
import { loadProjectRequirements } from '../mocks/projectRequirements'
import { ensureOnboardProcessing } from '../mocks/onboardPlanning'
import { addPlanningRun } from '../mocks/planningRuns'
import { planStatuses, planSummary, planTypes, satellites, stations, taskPlans, resolveTaskPlan } from '../mocks/taskPlans'
import type { PrototypeState } from '../types/prototype'
import type { RequirementRow } from '../types/requirements'
import type { TaskPlanRecord } from '../types/taskPlan'

const params=new URLSearchParams(window.location.search); const state=(params.get('state')||'normal') as PrototypeState
const onboardRecords = ensureOnboardProcessing()
const projectPlans: TaskPlanRecord[] = loadProjectRequirements().flatMap(row => (row.plans || []).filter(plan => plan.type !== '数传计划').map(plan => ({
  ...resolveTaskPlan(plan.no, row.taskNo), arcId: onboardRecords.find(item => item.planNo === plan.no)?.arcId || '待确认', satellite: row.satellite, type: plan.type,
  priority: row.priority, status: (['已取消', '已完成', '已上星', '已发送', '待发送', '规划成功'].includes(plan.status) ? plan.status : '待确认') as TaskPlanRecord['status'],
  createdAt: row.createdAt, executeStartAt: row.startAt, executeEndAt: row.endAt,
})))
const source=ref([...projectPlans, ...taskPlans.map(item=>({...item}))]); const selected=ref<any[]>([]); const expanded=ref(false); const busy=ref(false); const currentPage=ref(1); const pageSize=ref(30)
const detailVisible=ref(false); const detailRecord=ref<TaskPlanRecord|null>(null)
const manualPlanVisible=ref(false)
const semiVisible=ref(false); const semiPlanNo=ref('')
const requirementVisible=ref(false); const requirementRecord=ref<RequirementRow|null>(null)
const filters=reactive({planNo:'',createdRange:[] as string[],status:'',type:'',priority:'',satellite:'',station:'',arcId:''}); const applied=ref({...filters,createdRange:[] as string[]})
const rows=computed(()=>source.value.filter(row=>{const f=applied.value;return(!f.planNo||row.planNo.includes(f.planNo))&&(!f.status||row.status===f.status)&&(!f.type||row.type===f.type)&&(!f.priority||row.priority===Number(f.priority))&&(!f.satellite||row.satellite===f.satellite)&&(!f.station||row.station.includes(f.station))&&(!f.arcId||row.arcId.includes(f.arcId))&&(!f.createdRange.length||(row.createdAt>=f.createdRange[0]&&row.createdAt<=f.createdRange[1]))}))
onMounted(async()=>{if(params.get('detail')==='open'){const requested=params.get('planNo');const row=requested?source.value.find(item=>item.planNo===requested):source.value[0];if(row){if(requested){filters.planNo=requested;applied.value={...applied.value,planNo:requested}}openDetail(row)}else ElMessage.warning(`未找到计划 ${requested}`)}const action=params.get('confirm');if(action&&['send','delete','cancel','complete'].includes(action)){await nextTick();void runRisk(action,[source.value[0]])}})
function query(){applied.value={...filters,createdRange:[...filters.createdRange]};ElMessage.success(`查询完成，共 ${rows.value.length} 条证据样例`)}
function reset(){Object.assign(filters,{planNo:'',createdRange:[],status:'',type:'',priority:'',satellite:'',station:'',arcId:''});applied.value={...filters,createdRange:[]};ElMessage.success('筛选条件已重置')}
function openDetail(row:unknown){detailRecord.value=row as TaskPlanRecord;detailVisible.value=true}
function openRequirementDetail(taskNo:string){const row=requirementRows.find(item=>item.taskNo===taskNo);if(!row){ElMessage.warning(`任务 ${taskNo} 的详情证据待确认`);return}requirementRecord.value=row;requirementVisible.value=true}
function edit(){ElMessage.warning('任务计划编辑字段与校验规则待确认')}
function exportRows(){ElMessage.success('任务计划导出已生成')}
function manualCreate(){manualPlanVisible.value=true}
function openDataPlanning(){const eligible=selected.value.filter((item:TaskPlanRecord)=>['单星','协同','应急','双星'].includes(item.type)&&['待发送','已发送'].includes(item.status));semiPlanNo.value=eligible.length===1?eligible[0].planNo:'';semiVisible.value=true}
function completeDataPlanning(){addPlanningRun();ElMessage.success('数传规划已加入规划记录')}
async function runRisk(action:string,target=selected.value){if(!target.length)return ElMessage.warning('请先选择任务计划');const names:{[key:string]:string}={send:'发送',delete:'删除',cancel:'取消',complete:'完成'};const label=names[action];try{await ElMessageBox.confirm(`确认${label}已选择的 ${target.length} 条任务计划吗？真实状态迁移与后端影响待确认。`,`${label}任务计划确认`,{type:action==='delete'?'warning':'info',confirmButtonText:`确认${label}`,cancelButtonText:'返回检查'})}catch{return}busy.value=true;await new Promise(r=>window.setTimeout(r,500));if(action==='delete'){const ids=new Set(target.map(x=>x.planNo));source.value=source.value.filter(x=>!ids.has(x.planNo))}busy.value=false;selected.value=[];ElMessage.success(`${label}操作完成`)}
function statusType(status:string){return status==='待发送'?'warning':status==='执行失败'?'danger':status==='已完成'?'success':status==='已取消'?'info':'primary'}
</script>
<template><section class="requirement-page task-plan-page"><PageHeader title="任务计划表"/><PrototypeStatePanel v-if="state!=='normal'" :state="state" subject="任务计划"/><template v-else>
  <section class="plan-summary" aria-label="任务计划状态统计">
    <article class="plan-summary-total" :data-tone="planSummary[0].tone"><span>{{ planSummary[0].label }}</span><strong>{{ planSummary[0].value }}</strong><small>任务计划</small></article>
    <div class="plan-summary-statuses"><article v-for="item in planSummary.slice(1)" :key="item.label" :data-tone="item.tone"><span><i aria-hidden="true"/>{{ item.label }}</span><strong>{{ item.value }}</strong></article></div>
  </section>
  <div class="filter-panel"><el-form class="filter-form task-plan-filter" label-position="left"><el-form-item label="任务计划号"><el-input v-model="filters.planNo" placeholder="请输入" clearable/></el-form-item><el-form-item class="date-field" label="创建时间"><el-date-picker v-model="filters.createdRange" type="datetimerange" value-format="YYYY-MM-DD HH:mm:ss" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间"/></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" placeholder="请选择" clearable><el-option v-for="x in planStatuses" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="计划类型"><el-select v-model="filters.type" placeholder="请选择" clearable><el-option v-for="x in planTypes" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item v-show="expanded" label="优先级"><el-select v-model="filters.priority" placeholder="请选择" clearable><el-option v-for="x in 16" :key="x" :label="String(x)" :value="String(x)"/></el-select></el-form-item><el-form-item v-show="expanded" label="执行卫星"><el-select v-model="filters.satellite" placeholder="请选择" clearable><el-option v-for="x in satellites" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item v-show="expanded" label="执行地面站"><el-select v-model="filters.station" placeholder="请选择" clearable><el-option v-for="x in stations" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item v-show="expanded" label="弧段"><el-input v-model="filters.arcId" placeholder="请输入" clearable/></el-form-item></el-form><div class="filter-actions"><el-button type="primary" :icon="Search" @click="query">查 询</el-button><el-button :icon="Refresh" @click="reset">重 置</el-button><el-button :icon="Download" @click="exportRows">导 出</el-button></div><button class="expand-filter" type="button" :aria-expanded="expanded" :aria-label="expanded?'收起筛选条件':'展开筛选条件'" @click="expanded=!expanded">⌄</button></div>
  <div class="batch-actions plan-batch-actions"><el-button-group class="plan-core-actions"><el-button type="primary" :icon="Promotion" :loading="busy" @click="runRisk('send')">发送</el-button><el-button :icon="Edit" @click="edit">编辑</el-button><el-button type="danger" plain :icon="Delete" @click="runRisk('delete')">删除</el-button><el-button :icon="CircleClose" @click="runRisk('cancel')">取消</el-button><el-button type="success" plain :icon="CircleCheck" @click="runRisk('complete')">完成</el-button><el-button @click="openDataPlanning">数传规划</el-button></el-button-group><el-button class="manual-create" :icon="Plus" @click="manualCreate">手动创建计划</el-button><span>查询时间：2026-09-10 10:17:21 · 北京时间（UTC+8）</span></div>
  <div class="table-region"><el-table :data="rows" height="100%" class="requirement-table" @selection-change="selected=$event"><el-table-column type="selection" width="42" fixed="left"/><el-table-column prop="planNo" label="计划编号" min-width="110" fixed="left"/><el-table-column prop="arcId" label="弧段ID" min-width="175" show-overflow-tooltip/><el-table-column prop="satellite" label="执行卫星" min-width="90"/><el-table-column prop="type" label="计划类型" min-width="85"/><el-table-column prop="priority" label="优先级" width="76" align="center"/><el-table-column label="状态" min-width="90" align="center"><template #default="{row}"><el-tag :type="statusType(row.status)" effect="light">{{ row.status }}</el-tag></template></el-table-column><el-table-column prop="latestUploadAt" label="计划最晚上星时间" min-width="165"/><el-table-column prop="executeStartAt" label="计划开始执行时间" min-width="165"/><el-table-column prop="createdAt" label="创建时间" min-width="165"/><el-table-column prop="sentAt" label="发送时间" min-width="165"/><el-table-column prop="station" label="执行测站" min-width="140"/><el-table-column label="关联任务编号" min-width="180"><template #default="{row}"><button class="link-button" :aria-label="`查看任务 ${row.requirementNo}`" @click="openRequirementDetail(row.requirementNo)">{{ row.requirementNo }}</button></template></el-table-column><el-table-column prop="metaTaskNo" label="关联元号" min-width="180"/><el-table-column label="是否异常" width="80" align="center"><template #default="{row}"><el-tag :type="row.abnormal?'danger':'info'" effect="plain">{{ row.abnormal?'是':'否' }}</el-tag></template></el-table-column><el-table-column prop="abnormalCount" label="异常次数" width="84" align="center"/><el-table-column prop="abnormalReason" label="异常原因" min-width="260" show-overflow-tooltip/><el-table-column label="操作" width="132" fixed="right"><template #default="{row}"><div class="icon-actions"><el-button link type="primary" :icon="Upload" aria-label="发送计划" title="发送" @click="runRisk('send',[row])"/><el-button link type="primary" :icon="Edit" aria-label="编辑计划" title="编辑" @click="edit"/><el-button link type="primary" :icon="View" aria-label="查看计划" title="查看" @click="openDetail(row)"/></div></template></el-table-column></el-table></div>
  <div class="pagination-bar"><el-pagination v-model:current-page="currentPage" v-model:page-size="pageSize" background layout="total, sizes, prev, pager, next, jumper" :total="559" :page-sizes="[10,30,50,100,200]"/></div>
</template><PlanDetailDialog v-model:visible="detailVisible" :record="detailRecord"/><RequirementDialog v-model:visible="requirementVisible" mode="detail" :row="requirementRecord"/><ManualPlanDialog v-model:visible="manualPlanVisible" default-type="数传"/><SemiAutomaticPlanningDialog v-model:visible="semiVisible" initial-mode="data" :initial-plan-no="semiPlanNo" @completed="completeDataPlanning"/></section></template>
